/wp-content/uploads/2026/04/land-activities-before-footer-bg.webp\",\"reversed\":false} /-->\n\n<!-- wp:cwc/cards-section {\"variant\":\"staggered\",\"headingPrimary\":\"Mud-Splattered\",\"headingSecondary\":\"TRAIL RIDES\",\"headingSecondaryColor\":\"#395144\",\"sectionDescription\":\"Break free from the pavement and conquer Bicol’s rugged terrain. Power through mud, climb steep paths, and cruise scenic trails with guided ATV rides designed for both thrill and exploration.\",\"items\":[{\"title\":\"Scenic Routes\",\"image\":\"/wp-content/uploads/2026/04/scenic-routes.webp\",\"description\":\"Breathtaking views\",\"span\":3},{\"title\":\"Rugged Terrain\",\"image\":\"/wp-content/uploads/2026/04/rugged-terrain.webp\",\"description\":\"Built for the wild\",\"span\":3,\"offset\":true},{\"title\":\"Guided Tours\",\"image\":\"/wp-content/uploads/2026/04/guided-tours.webp\",\"description\":\"Safe, fun, and thrilling\",\"span\":3,\"offset\":true},{\"title\":\"Group Rides\",\"image\":\"/wp-content/uploads/2026/04/group-rides.webp\",\"description\":\"Better together\",\"span\":3}]} /-->\n\n<!-- wp:cwc/header-multi-image {\"titleAccent\":\"PICKLEBALL\",\"titleEnd\":\"\\u0026 COURT SPORTS\",\"description\":\"Switch gears with precision and pace. Whether you\'re rallying for fun or playing to win, our professionally surfaced courts offer the perfect space for both casual and competitive play.\",\"image1\":\"/wp-content/uploads/2026/04/pickleball-1.webp\",\"image2\":\"/wp-content/uploads/2026/04/pickleball-2.webp\"} /-->\n\n<!-- wp:cwc/feature-banner {\"backgroundImage\":\"/wp-content/uploads/2026/04/master-the-dirt-bg.webp\",\"titleLine1\":\"Master the Dirt Jumps\",\"titleAccent\":\"\",\"description\":\"Feel the rush of speed and control on a track built for adrenaline. With technical turns, dirt jumps, and high-speed straights, this circuit is made for riders ready to push their limits.\"} /-->\n\n<!-- wp:cwc/land-feature-split {\"titleStart\":\"EPIC TEAM\",\"titleAccent\":\"\\